// It is a normal test: review it and edit it like any other code.
// WARNING: when jevvium replayed these steps with plain Appium, they failed: element ("-ios predicate string:type == "XCUIElementTypeTextField" AND placeholderValue == "Maxim Winter"") still not existing after 15000ms
import { $, expect } from '@wdio/globals'

describe('checkout-plan', () => {
  it('Buy a backpack', async () => {
    // 1. From the Catalog, open the Sauce Labs Backpack and add it to the cart
    await $('//XCUIElementTypeCell[.//XCUIElementTypeStaticText[@label="Sauce Labs Backpack - Black"]]').click()
    await $('~AddToCart').click()
    // 2. Open the cart and proceed to checkout
    await $('~Cart-tab-item').click()
    await $('~ProceedToCheckout').click()
    // 3. Log in by picking bob@example.com from the list of usernames
    await $('-ios predicate string:type == "XCUIElementTypeButton" AND name == "bob@example.com"').click()
    // 4. Enter Jane Tester as the full name, 42 Example Street as the address line 1, Springfield as the city, 12345 as the zip code and United States as the country, then go to payment
    await $('-ios predicate string:type == "XCUIElementTypeButton" AND name == "Login"').click()
    await $('-ios predicate string:type == "XCUIElementTypeTextField" AND placeholderValue == "Rebecca Winter"').setValue('Jane Tester')
    await $('-ios predicate string:type == "XCUIElementTypeTextField" AND placeholderValue == "Mandorley 112"').setValue('42 Example Street')
    await $('-ios predicate string:type == "XCUIElementTypeTextField" AND placeholderValue == "Truro"').setValue('Springfield')
    await $('-ios predicate string:type == "XCUIElementTypeTextField" AND placeholderValue == "89750"').setValue('12345')
    await $('-ios predicate string:type == "XCUIElementTypeTextField" AND placeholderValue == "United Kingdom"').setValue('United States')
    await $('-ios predicate string:type == "XCUIElementTypeButton" AND name == "To Payment"').click()
    // 5. Enter Jane Tester as the name on card, 4111111111111111 as the card number, 1230 as the expiration date and 737 as the security code, then review the order
    await $('-ios predicate string:type == "XCUIElementTypeTextField" AND placeholderValue == "Maxim Winter"').setValue('Jane Tester')
    await $('-ios predicate string:type == "XCUIElementTypeTextField" AND placeholderValue == "3258 1265 7568 7896"').setValue('4111111111111111')
    await $('-ios predicate string:type == "XCUIElementTypeTextField" AND placeholderValue == "03/25"').setValue('1230')
    await $('-ios predicate string:type == "XCUIElementTypeTextField" AND placeholderValue == "123"').setValue('737')
    await $('-ios predicate string:type == "XCUIElementTypeButton" AND name == "Review Order"').click()
    // 6. Place the order
    await $('-ios predicate string:type == "XCUIElementTypeButton" AND name == "Place Order"').click()
    // Expected
    await expect($('~ContinueShopping')).toBeDisplayed()
    await expect($('-ios predicate string:label == "Checkout Complete"')).toBeDisplayed()
  })
})
